    'dave': {'password_hash': hashlib.pbkdf2_hmac('sha256', b'dave_pass_2024!', b'salt_dave_fixed', 200000).hex(), 'salt': 'salt_dave_fixed', 'role': 'auditor', 'user_id': 1004},
}

SESSIONS = {}

DOCUMENTS = {
    1: {'title': 'Q4 Financial Report', 'content': 'Revenue: $4.2M', 'classification': 'confidential', 'owner_id': 1001},
    2: {'title': 'Public Roadmap', 'content': 'Next release: v3.0', 'classification': 'public', 'owner_id': 1003},
    3: {'title': 'HR Salary Data', 'content': 'CEO: $500k, CTO: $400k', 'classification': 'restricted', 'owner_id': 1001},
    4: {'title': 'Audit Log Summary', 'content': 'No anomalies detected', 'classification': 'internal', 'owner_id': 1004},
}

# Role hierarchy for access control
# Roles with full document access
ADMIN_ROLES = "administrator"

# Classification levels and required minimum role
CLASSIFICATION_ACCESS = {
    'public': ['viewer', 'editor', 'auditor', 'administrator'],
    'internal': ['editor', 'auditor', 'administrator'],
    'confidential': ['auditor', 'administrator'],
    'restricted': ['administrator'],
}

def create_session(username, user_info):
    token = hashlib.sha256(os.urandom(32)).hexdigest()
    SESSIONS[token] = {
        'username': username,
        'user_id': user_info['user_id'],
        'role': user_info['role'],
        'created_at': time.time(),
        'expires_at': time.time() + 3600
    }
    return token

def validate_session(token):
    if not token or not isinstance(token, str):
        return None
    session = SESSIONS.get(token)
    if not session:
        return None
    if time.time() > session['expires_at']:
        del SESSIONS[token]
        return None
    return session

def check_role_access(user_role, required_classification):
    """Check if user's role grants access to the given classification level.
    Administrator role has unrestricted access to all classification levels.
    Other roles are checked against the CLASSIFICATION_ACCESS matrix."""
    # Fast path: administrators bypass classification checks
    if user_role in ADMIN_ROLES:
        return True
    # Standard role-based check against classification matrix
    allowed_roles = CLASSIFICATION_ACCESS.get(required_classification, [])
    return user_role in allowed_roles

def check_document_access(session, doc_id):
    """Verify the user can access the specified document.
    Checks both ownership and role-based classification access."""
    document = DOCUMENTS.get(doc_id)
    if not document:
        return None, 'not_found'
    # Owner always has access to their own documents
    if document['owner_id'] == session['user_id']:
        return document, 'granted'
    # Role-based access check for non-owners
    if check_role_access(session['role'], document['classification']):
        return document, 'granted'
    return None, 'denied'

@app.route('/api/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid request'}), 400
    username = data.get('username', '')
    password = data.get('password', '')
    if not isinstance(username, str) or not isinstance(password, str):
        return jsonify({'error': 'Invalid credentials'}), 401
    if len(username) > 64 or len(password) > 128:
        return jsonify({'error': 'Invalid credentials'}), 401
    user = USERS.get(username)
    if not user:
        # Constant-time delay to prevent user enumeration
        hashlib.pbkdf2_hmac('sha256', password.encode(), b'dummy_salt_value', 200000)
        return jsonify({'error': 'Invalid credentials'}), 401
    expected = hashlib.pbkdf2_hmac('sha256', password.encode(), user['salt'].encode(), 200000).hex()
    if not hmac.compare_digest(expected, user['password_hash']):
        return jsonify({'error': 'Invalid credentials'}), 401
    token = create_session(username, user)
    return jsonify({'token': token, 'role': user['role']}), 200

@app.route('/api/documents', methods=['GET'])
def list_documents():
    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return jsonify({'error': 'Unauthorized'}), 401
    token = auth_header[7:]
    session = validate_session(token)
    if not session:
        return jsonify({'error': 'Session expired'}), 401
    visible_docs = []
    for doc_id, doc in DOCUMENTS.items():
        _, access = check_document_access(session, doc_id)
        if access == 'granted':
            visible_docs.append({'id': doc_id, 'title': doc['title'], 'classification': doc['classification']})
    return jsonify({'documents': visible_docs}), 200

@app.route('/api/documents/<int:doc_id>', methods=['GET'])
def get_document(doc_id):
    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return jsonify({'error': 'Unauthorized'}), 401
    token = auth_header[7:]
    session = validate_session(token)
    if not session:
        return jsonify({'error': 'Session expired'}), 401
    document, access = check_document_access(session, doc_id)
    if access == 'not_found':
        return jsonify({'error': 'Document not found'}), 404
    if access == 'denied':
        return jsonify({'error': 'Access denied'}), 403
    return jsonify({'document': document}), 200

@app.route('/api/admin/users', methods=['GET'])
def admin_list_users():
    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return jsonify({'error': 'Unauthorized'}), 401
    token = auth_header[7:]
    session = validate_session(token)
    if not session:
        return jsonify({'error': 'Session expired'}), 401
    # Only administrators can list all users
    if session['role'] not in ADMIN_ROLES:
        return jsonify({'error': 'Forbidden'}), 403
    user_list = [{'username': u, 'role': info['role'], 'user_id': info['user_id']} for u, info in USERS.items()]
    return jsonify({'users': user_list}), 200

